class MauritaniaLeaflet(unittest.TestCase):
    def test_parse(self):
        table = mc.parse(LEAFLET + "\n" + SYNTHETIC)
        self.assertEqual(table["wilayas"]["Gorgol"], (210_612, 231_878, 442_490))
        hodh = table["moughataas"]["Hodh Chargui"]
        self.assertEqual(hodh["adelbagrou"]["figures"], (33_088, 39_767, 72_855))
        self.assertEqual(len(hodh["timbedra"]["communes"]), 5)
        self.assertEqual(table["moughataas"]["Brakna"]["bababe"]["figures"][2], 43_410)
        self.assertEqual(table["moughataas"]["Gorgol"]["lexeiba"]["figures"][2], 41_267)

    def test_build(self):
        table = mc.parse(LEAFLET + "\n" + SYNTHETIC)
        records, report = mc.build(table, ADMIN1, ADMIN2)
        self.assertEqual(report, [])
        by = {(r["level"], r["name"]): r for r in records}
        self.assertEqual(by[("admin2", "Amourj")]["population"]["value"], 78_148 + 72_855)
        self.assertIn("Adel Bagrou 72,855", by[("admin2", "Amourj")]["population_note"])
        self.assertEqual(by[("admin1", "Nouakchott")]["population"]["value"],
                         204_881 + 614_465 + 627_415)
        self.assertIn("three wilayas since 2014", by[("admin1", "Nouakchott")]["capital"]["note"])
        self.assertEqual(by[("admin1", "Inchiri")]["population"]["value"], 29_484 + 7_382)
        self.assertEqual(by[("admin1", "Dakhlet Nouadhibou")]["population"]["value"], 177_077)
        self.assertNotIn("value", by[("admin2", "Ksar")]["population"])
        self.assertNotIn("value", by[("admin2", "Ouad Naga")]["population"])
        self.assertIn("5 km outside", by[("admin2", "Selibabi")]["population_note"])
        counted = [r for r in records if r["level"] == "admin2" and "value" in r["population"]]
        self.assertEqual(len(counted), 47)
        # Each reason cites what it quotes: the leaflet for the ages it does not
        # give, and OCHA's boundaries, by which Nouakchott's lines are measured
        # (its Ksar, not its Toujounine, whose label it swaps with Teyarett's).
        ksar = by[("admin2", "Ksar")]
        self.assertIn("OCHA's Ksar, for one, lies mostly over what is drawn here as Ouad Naga",
                      ksar["population"]["note"])
        self.assertNotIn("Toujounine", ksar["population"]["note"])
        self.assertEqual([(s["name"], s["field"]) for s in ksar["sources"]][-1],
                         (mc.COD_AB["name"], "population note/sex_ratio note"))
        # The age report is cited for the reason that quotes it.
        self.assertIn((mc.AGES_SOURCE, "median_age note"),
                      [(s["name"], s["field"]) for s in ksar["sources"]])
        self.assertEqual(by[("admin2", "Amourj")]["sources"][0]["field"],
                         "population/sex_ratio/median_age note")
        self.assertEqual(by[("admin1", "Gorgol")]["sources"][0]["field"], "population/sex_ratio")
        # The office's own file, as the Internet Archive keeps it, is what is cited.
        gorgol = by[("admin1", "Gorgol")]["sources"][0]
        self.assertEqual(gorgol["page"],
                         "https://ansade.mr/wp-content/uploads/2024/09/Depliant-RGPH5-1.pdf")
        self.assertTrue(gorgol["url"].startswith("https://web.archive.org/web/20250925063203id_/"))
        self.assertTrue(gorgol["url"].endswith(gorgol["page"]))
        self.assertEqual(ksar["sources"][0]["page"], gorgol["page"])



